/** Actual RemoteViews and editor lifecycle; lives only in the separate fixture APK. */
public final class WidgetOptionsSmoke extends Instrumentation {
 private Context c;private int checks;private AppWidgetHost host;private int first,second;private Snapshot data;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public void onStart(){Bundle out=new Bundle();try{c=getTargetContext();getUiAutomation();tests();out.putString("stream","PASS: widget options ("+checks+" assertions)\n");finish(Activity.RESULT_OK,out);}catch(Throwable t){try{Bitmap b=getUiAutomation().takeScreenshot();File dir=new File(c.getExternalFilesDir(null),"qa");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,"options-failure.png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}catch(Exception ignored){}out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,out);}finally{if(host!=null)host.deleteHost();}}
 private void tests()throws Exception{
  Store.clear(c,"");Store.putSetting(c,"language","vi");Store.putSetting(c,"theme","dark");Store.saveSession(c,"https://fixture.example.com","mv1_"+String.join("",Collections.nCopies(43,"a")),System.currentTimeMillis()+3600000);
  long now=System.currentTimeMillis();JSONArray servers=new JSONArray();for(int i=0;i<6;i++)servers.put(new JSONObject().put("id","option"+i).put("name",i==0?"GOVA · Main VPS":"Server "+(i+1)).put("state",i==2?"offline":"online").put("observedAt",now).put("cpuPercent",24+i*4).put("memoryPercent",62).put("diskPercent",45));data=new Snapshot(new JSONObject().put("version",1).put("generatedAt",now).put("worker",new JSONObject().put("enabled",true).put("online",true).put("intervalSeconds",60)).put("servers",servers).toString());Store.snapshot(c,data,Store.generation());
  host=new AppWidgetHost(c,120042);host.deleteHost();first=bind(Widgets.Fleet.class);second=bind(Widgets.Single.class);check(Widgets.installed(c).length==2,"Own installed widgets found");
  Store.putSetting(c,"widget."+first,"[\"option0\"]");check(WidgetStyle.load(c,first).transparency==15&&WidgetStyle.load(c,first).layout.equals("auto"),"Legacy selection gets presentation defaults");check(Widgets.selection(c,first,data).size()==1,"Legacy selection preserved");
  check(WidgetStyle.parse("garbage").theme.equals("app"),"Corrupt style falls back");check(WidgetStyle.parse("{\"theme\":\"app|light\",\"transparency\":\"50\"}").theme.equals("app")&&WidgetStyle.parse("{\"transparency\":\"50\"}").transparency==15,"Exact enums and integer only");check(WidgetStyle.parse("{\"transparency\":-2}").transparency==0&&WidgetStyle.parse("{\"transparency\":10000000000}").transparency==100,"Opacity bounded without integer overflow");
  WidgetStyle a=new WidgetStyle();a.theme="dark";a.layout="bars";a.transparency=60;a.save(c,first);WidgetStyle b=new WidgetStyle();b.theme="light";b.layout="numbers";b.transparency=0;b.save(c,second);check(!WidgetStyle.load(c,first).json().equals(WidgetStyle.load(c,second).json()),"Independent widget style");
  for(final String theme:new String[]{"dark","light"})for(final String layout:new String[]{"auto","rings","bars","numbers"})for(final int alpha:new int[]{0,50,100})for(final int[] size:new int[][]{{110,110},{250,110},{280,180},{280,320},{350,440}}){final WidgetStyle style=new WidgetStyle();style.theme=theme;style.layout=layout;style.transparency=alpha;style.density=alpha==50?"compact":"comfortable";for(final boolean fleet:new boolean[]{false,true})runOnMainSync(new Runnable(){public void run(){View v=render(c,size[0],size[1],style,fleet);ImageView backdrop=(ImageView)v.findViewById(R.id.backdrop);check(backdrop.getImageAlpha()==style.alpha(),"Native background alpha");check(v.findViewById(R.id.body).getAlpha()==1f&&Color.alpha(((TextView)v.findViewById(R.id.headline)).getCurrentTextColor())==255,"Ink stays opaque");check(v.findViewById(R.id.configure).getWidth()>0&&v.findViewById(R.id.configure).getHeight()>0,"Visible settings gear");Bitmap chart=((BitmapDrawable)((ImageView)v.findViewById(R.id.visual)).getDrawable()).getBitmap();check(chart.getAllocationByteCount()<=720000,"Bounded drawing budget");View stamp=v.findViewById(R.id.stamp);int[] pos=new int[2];stamp.getLocationInWindow(pos);check(stamp.getHeight()>0&&stamp.getBottom()<=v.getHeight(),"Timestamp retained");if((alpha==50&&size[0]==280)||(alpha==100&&size[0]==250))save(v,"options-"+theme+"-"+layout+"-"+alpha+"-"+(fleet?"fleet":"single")+"-"+size[0]+"x"+size[1]+".png");}});}
  android.content.res.Configuration cfg=new android.content.res.Configuration(c.getResources().getConfiguration());cfg.fontScale=1.3f;final Context large=c.createConfigurationContext(cfg);runOnMainSync(new Runnable(){public void run(){save(render(large,250,110,WidgetStyle.load(c,first),false),"options-font130-wide.png");}});
  Activity editor=open(first);setProgress(editor,75);check(WidgetStyle.load(c,first).transparency==60,"Preview does not save draft");choose(editor,"layout","Đồng hồ");choose(editor,"theme","Sáng dịu");choose(editor,"accent","Xanh ngọc");choose(editor,"density","Gọn");capture(editor,"widget-editor-light-choice.png");
  final Activity before=editor;ActivityMonitor monitor=addMonitor(WidgetSetupActivity.class.getName(),null,false);runOnMainSync(new Runnable(){public void run(){before.recreate();}});editor=waitForMonitorWithTimeout(monitor,5000);removeMonitor(monitor);check(editor!=null,"Editor recreated");waitForIdleSync();check(progress(editor)==75,"Draft opacity survives recreation");check(text(editor,"value:layout").equals("Đồng hồ")&&text(editor,"value:theme").equals("Sáng dịu"),"Draft choices survive recreation");click(editor,"style:cancel");check(WidgetStyle.load(c,first).transparency==60&&WidgetStyle.load(c,first).layout.equals("bars"),"Cancel discards every draft field");
  editor=open(first);choose(editor,"layout","Bar ngang");choose(editor,"theme","Tối");setProgress(editor,40);click(editor,"style:save");check(WidgetStyle.load(c,first).transparency==40&&WidgetStyle.load(c,first).layout.equals("bars"),"Save commits draft");check(WidgetStyle.load(c,second).theme.equals("light")&&WidgetStyle.load(c,second).transparency==0,"Saving one leaves other widget untouched");
  editor=open(first);click(editor,"style:reset");check(progress(editor)==15&&text(editor,"value:layout").equals("Tự động"),"Reset controls and preview");check(Widgets.selection(c,first,data).size()==1,"Appearance reset keeps selection");click(editor,"style:cancel");check(WidgetStyle.load(c,first).transparency==40,"Reset can be cancelled");
  editor=open(second);click(editor,"server:3");click(editor,"style:save");check(Widgets.selection(c,second,data).size()==1&&Widgets.selection(c,second,data).get(0).id.equals("option3"),"Single widget selects exactly one server");
  editor=open(first);click(editor,"server:0");click(editor,"style:save");check(!editor.isFinishing()&&Widgets.selection(c,first,data).size()==1,"Empty selection rejected without overwrite");click(editor,"style:cancel");
  editor=open(first);capture(editor,"widget-editor-dark.png");final Activity privateEditor=editor;monitor=addMonitor(WidgetSetupActivity.class.getName(),null,false);Store.clear(c,"");c.sendBroadcast(new Intent(Sync.CHANGED).setPackage(c.getPackageName()));editor=waitForMonitorWithTimeout(monitor,5000);removeMonitor(monitor);check(editor!=null,"Auth erasure refreshes open editor");waitForIdleSync();check(editor.findViewById(android.R.id.content).findViewWithTag("server:0")==null,"Revocation removes private server checklist");click(editor,"style:cancel");check(Store.snapshot(c)==null,"Editor never restores cleared cache");
  new Widgets().onDeleted(c,new int[]{first});check(Store.setting(c,"widget."+first,"").isEmpty()&&Store.setting(c,"widget.style."+first,"").isEmpty(),"Delete cleans only its settings");check(WidgetStyle.load(c,second).theme.equals("light"),"Delete preserves other widget");
 }
 private int bind(Class<?> type){int id=host.allocateAppWidgetId();Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,280);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,180);check(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(id,new ComponentName(c,type),options),"Bind actual owned widget");return id;}
 private View render(Context context,int width,int height,WidgetStyle style,boolean fleet){View v=Widgets.render(context,first,!fleet,width,height,data,style,fleet?data.servers:Collections.singletonList(data.servers.get(0))).apply(context,new FrameLayout(context));int w=Visuals.dp(context,width),h=Visuals.dp(context,height);v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);return v;}
 private Activity open(int id){Activity a=startActivitySync(new Intent(c,WidgetSetupActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(!a.isFinishing(),"Owned widget editor opens");return a;}
 private void click(final Activity a,final String tag){runOnMainSync(new Runnable(){public void run(){View v=a.findViewById(android.R.id.content).findViewWithTag(tag);check(v!=null,"Control "+tag);v.performClick();}});waitForIdleSync();}
 private String text(Activity a,String tag){return ((TextView)a.findViewById(android.R.id.content).findViewWithTag(tag)).getText().toString();}
 private int progress(Activity a){return ((SeekBar)a.findViewById(android.R.id.content).findViewWithTag("style:transparency")).getProgress();}
 private void setProgress(final Activity a,final int value){runOnMainSync(new Runnable(){public void run(){((SeekBar)a.findViewById(android.R.id.content).findViewWithTag("style:transparency")).setProgress(value);}});waitForIdleSync();}
 private void choose(Activity a,String control,String label)throws Exception{click(a,"style:"+control);getUiAutomation().waitForIdle(100,4000);long end=System.currentTimeMillis()+4000;boolean clicked=false;String seen="";while(!clicked&&System.currentTimeMillis()<end){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null){seen=root.toString();for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(label))if(label.contentEquals(n.getText()==null?"":n.getText())){Rect bounds=new Rect();n.getBoundsInScreen(bounds);if(!bounds.isEmpty()){long now=android.os.SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0));sendPointerSync(MotionEvent.obtain(now,now+30,MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0));clicked=true;break;}}}if(!clicked)Thread.sleep(50);}check(clicked,"Native choice "+label+" root="+seen);waitForIdleSync();check(text(a,"value:"+control).equals(label),"Choice updates in place");}
 private void capture(final Activity a,final String name)throws Exception{Thread.sleep(150);runOnMainSync(new Runnable(){public void run(){save(a.getWindow().getDecorView(),name);}});}
 private void save(View v,String name){try{Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);Paint p=new Paint();p.setShader(new LinearGradient(0,0,b.getWidth(),b.getHeight(),new int[]{0xFF92B8C4,0xFF526E93,0xFF262D4C},null,Shader.TileMode.CLAMP));cv.drawRect(0,0,b.getWidth(),b.getHeight(),p);v.draw(cv);File dir=new File(c.getExternalFilesDir(null),"qa");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}catch(Exception e){throw new RuntimeException(e);}}
}
